#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Ticket 01: mọi khoá và tài khoản mà lát cắt đầu cần, ghi vào .env ở gốc repo.
# Chạy bằng Git Bash:  bash scripts/setup-keys.sh
# Chạy lại được: giá trị đã có trong .env được giữ khi nhấn Enter.

TOTAL_STAGES=6

cd "$(dirname "${BASH_SOURCE[0]}")/.."

if command -v uv >/dev/null 2>&1; then PY=(uv run --quiet python)
elif command -v python3 >/dev/null 2>&1; then PY=(python3)
elif command -v python >/dev/null 2>&1; then PY=(python)
else echo "Cần uv hoặc python để đọc phản hồi của các dịch vụ." >&2; exit 1; fi
command -v curl >/dev/null 2>&1 || { echo "Cần curl." >&2; exit 1; }
[[ -t 0 ]] || { echo "Kịch bản này hỏi đáp trực tiếp; hãy chạy nó trong một terminal." >&2; exit 1; }

# clean VALUE bỏ khoảng trắng và ký tự xuống dòng thừa quanh một giá trị vừa dán.
clean() {
  local v="${1//$'\r'/}"
  v="${v#"${v%%[![:space:]]*}"}"
  printf '%s' "${v%"${v##*[![:space:]]}"}"
}

# json_get CODE đọc JSON từ stdin vào biến d rồi chạy CODE (Python). Hỏng thì im lặng.
json_get() {
  PYTHONUTF8=1 "${PY[@]}" -c "import json, os, sys
try:
    d = json.load(sys.stdin)
except ValueError:
    sys.exit(1)
$1" 2>/dev/null
}

# tg METHOD [JSON] gọi Bot API bằng $TELEGRAM_BOT_TOKEN và in phản hồi.
# Lỗi của curl bị giấu vì nó in cả địa chỉ, mà địa chỉ có chứa token.
tg() {
  local body="${2:-}"
  [[ -n "$body" ]] || body='{}'
  curl -sS --max-time 20 -X POST "https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/$1" \
    -H 'Content-Type: application/json' -d "$body" 2>/dev/null || true
}

# seen_chats KINDS in các cuộc trò chuyện bot vừa thấy thuộc các loại KINDS, mỗi dòng "mã<TAB>tên".
seen_chats() {
  tg getUpdates | KINDS="$1" json_get '
seen = {}
for u in d.get("result", []):
    for k in ("message", "my_chat_member", "channel_post"):
        c = (u.get(k) or {}).get("chat")
        if c and c["type"] in os.environ["KINDS"].split():
            ten = c.get("title") or " ".join(filter(None, [c.get("first_name"), c.get("last_name")]))
            seen[c["id"]] = ten
for ma, ten in seen.items():
    print(f"{ma}\t{ten}")' || true
}

# pick_chat KEY KINDS "tên gọi" tìm cuộc trò chuyện bot vừa thấy, hỏi lại cho chắc,
# kiểm tra với Telegram rồi ghi vào .env. Lặp tới khi được một mã đúng loại.
pick_chat() {
  local key="$1" kinds="$2" what="$3" seen count value kind ma ten
  while true; do
    seen=$(seen_chats "$kinds")
    count=$(grep -c . <<<"$seen" || true)
    value=""
    if [[ "$count" -eq 1 ]] && confirm "Dùng $what \"${seen#*$'\t'}\" (mã ${seen%%$'\t'*})?"; then
      value="${seen%%$'\t'*}"
    else
      if [[ "$count" -eq 0 ]]; then
        warn "Bot chưa thấy $what nào. Làm lại bước trên rồi nhấn Enter, hoặc dán mã nếu bạn đã biết."
      else
        say "Bot vừa thấy:"
        while IFS=$'\t' read -r ma ten; do say "  $ma  $ten"; done <<<"$seen"
      fi
      printf '  %sMã của %s (để trống để tìm lại):%s ' "$BOLD" "$what" "$RESET"
      read -r value || true
      value=$(clean "$value")
    fi
    [[ -n "$value" ]] || continue
    if [[ ! "$value" =~ ^-?[0-9]+$ ]]; then warn "Mã phải là một số."; continue; fi
    if [[ "$value" == "${TELEGRAM_BOT_TOKEN%%:*}" ]]; then
      warn "Đây là mã của chính con bot, không phải $what."; continue
    fi
    kind=$(tg getChat "{\"chat_id\":$value}" | json_get 'print(d["result"]["type"])' || true)
    if [[ " $kinds " == *" $kind "* ]]; then break; fi
    warn "Telegram không coi mã $value là $what (loại: ${kind:-không tìm thấy})."
  done
  printf -v "$key" '%s' "$value"
  write_env "$key" "$value"
}

# send_test CHAT_ID "nội dung" gửi một tin nhắn thử nếu người dùng đồng ý, và báo kết quả.
send_test() {
  local reply
  confirm "Gửi một tin nhắn thử để chắc bot gửi được?" || return 0
  reply=$(tg sendMessage "{\"chat_id\":$1,\"text\":\"$2\"}")
  if [[ "$(json_get 'print(d["ok"])' <<<"$reply" || true)" == "True" ]]; then
    say "${GREEN}✓${RESET} Đã gửi. Kiểm tra trong Telegram."
  else
    warn "Không gửi được: $(json_get 'print(d.get("description"))' <<<"$reply" || echo "không rõ lí do")"
  fi
  pause
}

# http_code CURL_ARGS... trả về mã HTTP của một lời gọi GET, hoặc 000 khi không kết nối được.
http_code() { curl -sS --max-time 30 -o /dev/null -w '%{http_code}' "$@" 2>/dev/null || true; }

banner "Bản tin tự động: khoá và tài khoản"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Telegram: bot và token"
say "Bot là tài khoản sẽ đăng Bản tin vào nhóm và nhắn riêng cho bạn."
note "Đã có token trong .env thì nhấn Enter ở câu hỏi bên dưới để giữ, không cần tạo bot mới."
open_url "https://t.me/BotFather"
step "Trong cuộc trò chuyện với @BotFather, gửi /newbot rồi đặt tên và username cho bot."
step "BotFather trả về token dạng 123456789:AA... Sao chép nó."
while true; do
  ask_secret TELEGRAM_BOT_TOKEN "Dán token của bot:"
  TELEGRAM_BOT_TOKEN=$(clean "$TELEGRAM_BOT_TOKEN")
  BOT_USERNAME=$(tg getMe | json_get 'print(d["result"]["username"])' || true)
  [[ -n "$BOT_USERNAME" ]] && break
  warn "Telegram không nhận token này (hoặc không kết nối được). Thử lại."
done
say "Bot của bạn: @$BOT_USERNAME"
write_env TELEGRAM_BOT_TOKEN "$TELEGRAM_BOT_TOKEN"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Telegram: nhóm thử"
say "Bản tin được đăng vào nhóm này. Mã nhóm là một số âm, khác với mã của bot."
step "Trong Telegram, tạo một nhóm mới (hoặc dùng nhóm có sẵn) và thêm @$BOT_USERNAME vào."
step "Trong nhóm đó, gửi đúng tin nhắn này:  /start@$BOT_USERNAME"
note "Bot chỉ đọc được tin nhắn dạng lệnh trong nhóm, nên cần lệnh này để nó biết tới nhóm."
pause "Gửi xong thì nhấn Enter để tìm mã nhóm."
pick_chat TELEGRAM_CHAT_ID "group supergroup" "nhóm"
send_test "$TELEGRAM_CHAT_ID" "Tin nhắn thử từ kịch bản cài đặt Bản tin tự động."
note "Nếu sau này Telegram nâng nhóm thành supergroup thì mã nhóm đổi; khi đó chạy lại kịch bản này."

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Telegram: mã người dùng của bạn"
say "Bot dùng mã này để nhắn riêng cho bạn khi một Kỳ hỏng, và để nhận ra Phản hồi của bạn."
open_url "https://t.me/$BOT_USERNAME"
step "Mở cuộc trò chuyện riêng với @$BOT_USERNAME và nhấn Start (hoặc gửi /start)."
note "Bot không nhắn trước được cho người chưa từng nhắn nó, nên bước này bắt buộc."
pause "Gửi xong thì nhấn Enter để tìm mã của bạn."
pick_chat TELEGRAM_OWNER_ID "private" "tài khoản"
send_test "$TELEGRAM_OWNER_ID" "Tin nhắn riêng thử từ kịch bản cài đặt Bản tin tự động."

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Endpoint LLM"
say "Mọi lời gọi LLM đi qua một endpoint tương thích OpenAI. Cần địa chỉ và khoá của nó."
note "Địa chỉ thường kết thúc bằng /v1. Lấy cả hai ở nơi bạn chạy hoặc thuê endpoint."
while true; do
  ask OPENAI_BASE_URL "Địa chỉ endpoint:"
  ask_secret OPENAI_API_KEY "Khoá của endpoint:"
  OPENAI_BASE_URL=$(clean "$OPENAI_BASE_URL"); OPENAI_BASE_URL="${OPENAI_BASE_URL%/}"
  OPENAI_API_KEY=$(clean "$OPENAI_API_KEY")
  MODELS=$(curl -sS --max-time 30 -H "Authorization: Bearer $OPENAI_API_KEY" \
    "$OPENAI_BASE_URL/models" 2>/dev/null \
    | json_get 'print("\n".join(sorted(str(m["id"]) for m in d["data"])))' || true)
  [[ -n "$MODELS" ]] && break
  warn "Không lấy được danh sách model từ $OPENAI_BASE_URL/models."
  confirm "Vẫn lưu hai giá trị này?" && break
done
write_env OPENAI_BASE_URL "$OPENAI_BASE_URL"
write_env OPENAI_API_KEY "$OPENAI_API_KEY"
if [[ -n "$MODELS" ]]; then
  say "Endpoint có $(grep -c . <<<"$MODELS") model:"
  while IFS= read -r model; do note "  $model"; done <<<"$MODELS"
  note "Ticket 02 sẽ thử từng model và chọn model cho từng vai trò."
fi
if [[ "$OPENAI_BASE_URL" == *localhost* || "$OPENAI_BASE_URL" == *127.0.0.1* ]]; then
  warn "Địa chỉ này chỉ dùng được trên máy này; khi đưa lên server cần một địa chỉ server tới được."
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Tavily: khoá tìm kiếm web"
say "Biên tập dùng Tavily để tìm bối cảnh cho một Tin."
open_url "https://app.tavily.com/home"
step "Đăng nhập hoặc tạo tài khoản; gói miễn phí đủ để bắt đầu."
step "Ở trang tổng quan, mục API Keys, sao chép khoá (bắt đầu bằng tvly-)."
ask_secret TAVILY_API_KEY "Dán khoá Tavily:"
TAVILY_API_KEY=$(clean "$TAVILY_API_KEY")
write_env TAVILY_API_KEY "$TAVILY_API_KEY"
code=$(http_code -H "Authorization: Bearer $TAVILY_API_KEY" "https://api.tavily.com/usage")
if [[ "$code" == "200" ]]; then say "${GREEN}✓${RESET} Tavily nhận khoá này."
else warn "Tavily trả về mã $code khi kiểm tra khoá. Xem lại khoá rồi chạy lại kịch bản nếu cần."; fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Langfuse: khoá ghi vết"
say "Mọi lần gọi của agent được ghi vết lên Langfuse bản cloud."
open_url "https://cloud.langfuse.com"
step "Đăng nhập hoặc tạo tài khoản, rồi tạo một organization và một project (ví dụ: bulletin)."
step "Trong project, mở Settings → API Keys → Create new API keys."
step "Sao chép Public Key (pk-lf-...) và Secret Key (sk-lf-...). Secret Key chỉ hiện một lần."
ask LANGFUSE_PUBLIC_KEY "Dán Public Key:"
ask_secret LANGFUSE_SECRET_KEY "Dán Secret Key:"
say "Địa chỉ theo vùng dữ liệu đã chọn khi tạo tài khoản:"
note "  EU: https://cloud.langfuse.com    US: https://us.cloud.langfuse.com"
note "  Nhật: https://jp.cloud.langfuse.com"
ask LANGFUSE_BASE_URL "Địa chỉ Langfuse (để trống là vùng EU):"
LANGFUSE_PUBLIC_KEY=$(clean "$LANGFUSE_PUBLIC_KEY")
LANGFUSE_SECRET_KEY=$(clean "$LANGFUSE_SECRET_KEY")
LANGFUSE_BASE_URL=$(clean "$LANGFUSE_BASE_URL"); LANGFUSE_BASE_URL="${LANGFUSE_BASE_URL%/}"
[[ -n "$LANGFUSE_BASE_URL" ]] || LANGFUSE_BASE_URL="https://cloud.langfuse.com"
write_env LANGFUSE_PUBLIC_KEY "$LANGFUSE_PUBLIC_KEY"
write_env LANGFUSE_SECRET_KEY "$LANGFUSE_SECRET_KEY"
write_env LANGFUSE_BASE_URL "$LANGFUSE_BASE_URL"
code=$(http_code -u "$LANGFUSE_PUBLIC_KEY:$LANGFUSE_SECRET_KEY" "$LANGFUSE_BASE_URL/api/public/projects")
if [[ "$code" == "200" ]]; then say "${GREEN}✓${RESET} Langfuse nhận cặp khoá này."
else warn "Langfuse trả về mã $code. Thường là sai vùng (EU/US) hoặc dán nhầm khoá; chạy lại kịch bản để sửa."; fi
pause

finish
say "Tiếp theo: uv run bulletin init, rồi uv run bulletin run tech"
printf '\n'
